int[][] iv = {{0, 10}, {1, 2}, {3, 4}};
Arrays.sort(iv, (p, q) -> p[0] - q[0]);
int cnt = 0, end = -1;
for (int[] p : iv)
    if (p[0] >= end) { cnt++; end = p[1]; }
System.out.println(cnt);

const iv = [[0, 10], [1, 2], [3, 4]];
iv.sort((p, q) => p[0] - q[0]);
let cnt = 0, end = -1;
for (const [s, e] of iv)
  if (s >= end) { cnt++; end = e; }
console.log(cnt);

vector<pair<int, int>> iv =
    {{0, 10}, {1, 2}, {3, 4}};
sort(iv.begin(), iv.end());
int cnt = 0, end = -1;
for (auto [s, e] : iv)
    if (s >= end) { cnt++; end = e; }
cout << cnt;

int[][] iv = {{0, 10}, {1, 2}, {3, 4}};
Arrays.sort(iv, (p, q) -> p[1] - q[1]);
int cnt = 0, end = -1;
for (int[] p : iv)
    if (p[0] >= end) { cnt++; end = p[1]; }
System.out.println(cnt);

const iv = [[0, 10], [1, 2], [3, 4]];
iv.sort((p, q) => p[1] - q[1]);
let cnt = 0, end = -1;
for (const [s, e] of iv)
  if (s >= end) { cnt++; end = e; }
console.log(cnt);

vector<pair<int, int>> iv =
    {{0, 10}, {1, 2}, {3, 4}};
sort(iv.begin(), iv.end(), [](auto a, auto b) {
    return a.second < b.second;
});
int cnt = 0, end = -1;
for (auto [s, e] : iv)
    if (s >= end) { cnt++; end = e; }
cout << cnt;
